        t->init();

        assert(!t->isNull());
        assert(t->isEmpty());

        string inp4hash("some input text 4 hash");
        eevm::KeccakHash tx_hash = eevm::keccak_256(inp4hash);

        TRACE_ENCLAVE("1");
        auto hash = dev::h256(tx_hash.data(), dev::h256::ConstructFromPointer);
        TRACE_ENCLAVE("2");
        t->insert(hash, inp4hash);
        TRACE_ENCLAVE("3");
